// ─── Dil algılama ───────────────────────────────────────────
const SUPPORTED = ["tr", "en", "de"];

export function detectLang() {
  // 1) Kullanıcının kayıtlı tercihi
  const saved = localStorage.getItem("muuvlang");
  if (saved && SUPPORTED.includes(saved)) return saved;
  // 2) Tarayıcı/telefon dili
  const browser = (navigator.language || navigator.userLanguage || "en").slice(0, 2).toLowerCase();
  // 3) Desteklenmiyorsa İngilizce fallback
  return SUPPORTED.includes(browser) ? browser : "en";
}

// ─── Çeviri fonksiyonu ──────────────────────────────────────
export function createT(lang) {
  /**
   * t("nav.home")          → "Home" (en)
   * t("teams.roles.owner") → "Owner"
   * t("sports.Futbol")     → "Football"
   */
  return function t(key) {
    const parts = key.split(".");
    let node = translations;
    for (const part of parts) {
      if (node == null) return key;
      node = node[part];
    }
    if (node && typeof node === "object" && node[lang]) return node[lang];
    if (node && typeof node === "object" && node["en"]) return node["en"]; // fallback EN
    if (node && typeof node === "object" && node["tr"]) return node["tr"]; // fallback TR
    return key; // key kendisi döner
  };
}
